function scare(){jumpscare=18;const el=document.getElementById('scare');el.classList.add('show');if(sound)beep(90,.32);setTimeout(()=>el.classList.remove('show'),370);showToast('¡El fantasma pálido! No puede hacerte daño…')}
function move(dt){let dir=0;if(key.ArrowLeft||key.KeyA||held.left)dir--;if(key.ArrowRight||key.KeyD||held.right)dir++;if(dir&&!player.hidden){player.x=clamp(player.x+dir*dt*.17,65,935);player.face=dir;player.step+=dt*.019}if(player.hidden)return;
 if((key.ArrowUp||key.KeyW||held.up)&&Math.abs(player.x-stairAt(player.f))<54){changeFloor(player.f===0?1:player.f===2?-1:(stairAt(player.f)===100?1:-1));key.ArrowUp=key.KeyW=false;held.up=false}
 if((key.ArrowDown||key.KeyS||held.down)&&Math.abs(player.x-stairAt(player.f))<54){changeFloor(player.f===0?1:player.f===2?-1:(stairAt(player.f)===100?1:-1));key.ArrowDown=key.KeyS=false;held.down=false}}
function ai(dt){tick+=dt;if(flash){battery=Math.max(0,battery-dt*.0032);if(battery===0){flash=false;showToast('La batería se agotó.');updateHUD()}}if(decoy.t>0){decoy.t-=dt;if(decoy.t<=0)decoy.x=0}
 if(hunter.stun>0)hunter.stun-=dt;else{if(hunter.f!==player.f&&tick%6400<dt&&Math.random()<.75){hunter.f=player.f;hunter.x=player.x<500?920:80}if(hunter.f===player.f&&!player.hidden){let tx=decoy.t>0&&decoy.f===hunter.f?decoy.x:player.x;let dx=tx-hunter.x;if(Math.abs(dx)>20)hunter.x=clamp(hunter.x+Math.sign(dx)*dt*.025,65,935);if(Math.abs(hunter.x-player.x)<32){sanity-=dt*.025;if(sanity<=0){reset();return}}else if(Math.abs(hunter.x-player.x)<140)sanity-=dt*.002}}
 ghostTimer-=dt;if(ghostTimer<=0&&!harmless.show){harmless.show=true;harmless.f=player.f;harmless.x=clamp(player.x+(player.x<500?1:-1)*(150+Math.random()*90),70,930);harmless.t=420;ghostTimer=1000+Math.random()*900}if(harmless.show){harmless.t-=dt;if(harmless.f===player.f&&Math.abs(harmless.x-player.x)<67&&!player.hidden){harmless.show=false;scare();ghostTimer=1200+Math.random()*1000}else if(harmless.t<=0)harmless.show=false}
 if(jumpscare>0)jumpscare--;if(Math.floor(tick/300)!==roomHint){roomHint=Math.floor(tick/300);let room=Math.min(4,Math.floor(player.x/200));document.getElementById('floorTag').textContent=floorName(player.f)+' · '+(player.f+1)+' / 3  ·  '+floors[player.f].rooms[room].toUpperCase()}if(Math.floor(tick/500)!==Math.floor((tick-dt)/500))updateHUD()}
function beep(freq,duration){try{let ac=new(window.AudioContext||window.webkitAudioContext)(),o=ac.createOscillator(),g=ac.createGain();o.frequency.value=freq;o.type='sawtooth';g.gain.value=.035;o.connect(g);g.connect(ac.destination);o.start();g.gain.exponentialRampToValueAtTime(.001,ac.currentTime+duration);o.stop(ac.currentTime+duration)}catch(e){}}

